(6602892, 984683, 41129, '<td valign="top">now this is a defining feature.. lol.. great focus, love it</td>', 'now this is a defining feature.. lol.. great focus, love it', '2011-11-24 20:43:10.000000', NULL, 1),
(6602896, 984659, 46918, '<td valign="top">Alfalfa lives!!!!!! Good shot..I like the lighting...Perfect for this shot...I give a 7.</td>', 'Alfalfa lives!!!!!! Good shot..I like the lighting...Perfect for this shot...I give a 7.', '2011-11-24 20:48:12.000000', NULL, 1),
(6602897, 984751, 46918, '<td valign="top">Great textures in this shot.</td>', 'Great textures in this shot.', '2011-11-24 20:49:00.000000', NULL, 1),
(6602898, 985163, 46918, '<td valign="top">ok I understand what you were going for but the shot is too grainy and to bright. The lighting is way too harsh for the image</td>', 'ok I understand what you were going for but the shot is too grainy and to bright. The lighting is way too harsh for the image', '2011-11-24 20:51:19.000000', NULL, 1),
(6602904, 984867, 30049, '<td valign="top">DNMC - for real.  I''ve been here 8 years and I think that may be the first time I''ve actually put that in a comment, but come on - REALLY?!  From the challenge description: "Take a picture of a person''s defining feature. Find someone, find what defines them..."  Talk about shoehorning a "pretty picture".</td>', 'DNMC - for real.  I''ve been here 8 years and I think that may be the first time I''ve actually put that in a comment, but come on - REALLY?!  From the challenge description: "Take a picture of a person''s defining feature. Find someone, find what defines them..."  Talk about shoehorning a "pretty picture".', '2011-11-24 21:01:18.000000', NULL, 1),
(6603020, 984766, 30364, '<td valign="top">It looks like him.  I think it IS him. And it''s good.  Top ten.</td>', 'It looks like him.  I think it IS him. And it''s good.  Top ten.', '2011-11-25 01:13:07.000000', NULL, 1),
(6603022, 984995, 30364, '<td valign="top">Best eyes in show.  Top ten.  Thank you.</td>', 'Best eyes in show.  Top ten.  Thank you.', '2011-11-25 01:15:09.000000', NULL, 1),
(6603027, 985160, 30364, '<td valign="top">It''s rare I like a ribbon winner, but this is uncommonly beautiful.  Top ten.  Thank you.</td>', 'It''s rare I like a ribbon winner, but this is uncommonly beautiful.  Top ten.  Thank you.', '2011-11-25 01:23:12.000000', NULL, 1),
(6603034, 985119, 30364, '<td valign="top">I can''t say ''no'' to this (and I say ''no'' a lot).  Top ten.  Thank you.</td>', 'I can''t say ''no'' to this (and I say ''no'' a lot).  Top ten.  Thank you.', '2011-11-25 01:36:50.000000', NULL, 1),
